import itertools

def solve_small(n):
    black_squares = []
    white_squares = []
    for r in range(n):
        for c in range(n):
            if (r + c) % 2 == 0:
                black_squares.append((r, c))
            else:
                white_squares.append((r, c))

    b_set = set(black_squares)

    # All possible L-trominoes
    l_trominoes = []
    for r in range(n - 1):
        for c in range(n - 1):
            # 2x2 square: (r,c), (r,c+1), (r+1,c), (r+1,c+1)
            sq = [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]
            for i in range(4):
                # Remove one square to get an L-tromino
                tromino = [sq[j] for j in range(4) if j != i]
                l_trominoes.append(set(tromino))

    # We want to cover all black squares with minimum number of L-trominoes.
    # This is a set cover problem, but the sets must be disjoint.
    # Since the number of black squares is small, we can use backtracking.

    min_n = [float('inf')]

    def backtrack(remaining_black, used_squares, count):
        if not remaining_black:
            min_n[0] = min(min_n[0], count)
            return

        if count >= min_n[0]:
            return

        # Pick a black square to cover
        b = next(iter(remaining_black))

        # Try all trominoes that cover this black square
        for tromino in l_trominoes:
            if b in tromino:
                if tromino.isdisjoint(used_squares):
                    backtrack(remaining_black - (tromino & b_set), used_squares | tromino, count + 1)

    backtrack(b_set, set(), 0)
    return min_n[0]

