                l_trominoes_2b.append(frozenset([(r,c+1), (r,c), (r+1,c)]))
                l_trominoes_2b.append(frozenset([(r,c+1), (r+1,c+1), (r+1,c)]))

    max_x = [0]
    def backtrack(idx, used_squares, count):
        max_x[0] = max(max_x[0], count)
        for i in range(idx, len(l_trominoes_2b)):
            tromino = l_trominoes_2b[i]
            if tromino.isdisjoint(used_squares):
                backtrack(i + 1, used_squares | tromino, count + 1)

